import{_ as n,o as i,c as e,a2 as l}from"./chunks/framework.DBU8LMUS.js";const g=JSON.parse('{"title":"Memulai","description":"","frontmatter":{"title":"Memulai","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/mulai.md","filePath":"latest/mulai.md","lastUpdated":1786334463000}'),r={name:"latest/mulai.md"};function t(u,a,m,d,s,o){return i(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="memulai" tabindex="-1">Memulai <a class="header-anchor" href="#memulai" aria-label="Permalink to &quot;Memulai&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Modul ini menjelaskan langkah-langkah awal menggunakan aplikasi ILUNI FT ELEKTRO UNPAK: membuat akun, memverifikasi email, masuk (login), mengatur ulang kata sandi, dan keluar dari akun.</p><h2 id="mendaftar-akun" tabindex="-1">Mendaftar Akun <a class="header-anchor" href="#mendaftar-akun" aria-label="Permalink to &quot;Mendaftar Akun&quot;">​</a></h2><h3 id="membuka-halaman-pendaftaran" tabindex="-1">Membuka Halaman Pendaftaran <a class="header-anchor" href="#membuka-halaman-pendaftaran" aria-label="Permalink to &quot;Membuka Halaman Pendaftaran&quot;">​</a></h3><ol><li>Buka aplikasi di peramban Anda.</li><li>Klik tombol <strong>Daftar</strong> pada menu navigasi di bagian atas halaman.</li><li>Anda akan diarahkan ke halaman pendaftaran.</li></ol><h3 id="mengisi-formulir-pendaftaran" tabindex="-1">Mengisi Formulir Pendaftaran <a class="header-anchor" href="#mengisi-formulir-pendaftaran" aria-label="Permalink to &quot;Mengisi Formulir Pendaftaran&quot;">​</a></h3><ol><li>Isi <strong>Nama Lengkap</strong> sesuai data Anda.</li><li>Isi <strong>Email</strong> yang aktif (email ini akan digunakan untuk masuk dan menerima verifikasi).</li><li>Buat <strong>Kata Sandi</strong> dengan minimal 8 karakter.</li><li>Klik tombol <strong>Daftar</strong>.</li></ol><h3 id="memverifikasi-email" tabindex="-1">Memverifikasi Email <a class="header-anchor" href="#memverifikasi-email" aria-label="Permalink to &quot;Memverifikasi Email&quot;">​</a></h3><ol><li>Setelah mendaftar, buka kotak masuk email Anda.</li><li>Cari pesan verifikasi dari aplikasi ILUNI FT ELEKTRO UNPAK.</li><li>Klik tautan <strong>Verifikasi email</strong> di dalam pesan tersebut.</li><li>Kembali ke aplikasi lalu masuk dengan akun Anda.</li></ol><div class="tip custom-block"><p class="custom-block-title">Catatan</p><p>Verifikasi email wajib dilakukan sebelum Anda dapat masuk dan menggunakan fitur-fitur yang memerlukan akun. Jika tidak menerima email, periksa folder spam atau ulangi permintaan verifikasi.</p></div><h2 id="masuk-login" tabindex="-1">Masuk (Login) <a class="header-anchor" href="#masuk-login" aria-label="Permalink to &quot;Masuk (Login)&quot;">​</a></h2><ol><li>Klik menu <strong>Masuk</strong> pada navigasi.</li><li>Masukkan <strong>email</strong> dan <strong>kata sandi</strong> yang telah didaftarkan.</li><li>Klik tombol <strong>Masuk</strong>.</li></ol><p>Setelah berhasil masuk, Anda akan diarahkan ke halaman beranda. Menu navigasi akan menampilkan menu <strong>Profil Saya</strong> dan opsi <strong>Keluar</strong>.</p><h2 id="lupa-kata-sandi" tabindex="-1">Lupa Kata Sandi <a class="header-anchor" href="#lupa-kata-sandi" aria-label="Permalink to &quot;Lupa Kata Sandi&quot;">​</a></h2><h3 id="meminta-tautan-atur-ulang" tabindex="-1">Meminta Tautan Atur Ulang <a class="header-anchor" href="#meminta-tautan-atur-ulang" aria-label="Permalink to &quot;Meminta Tautan Atur Ulang&quot;">​</a></h3><ol><li>Pada halaman masuk, klik tautan <strong>Lupa kata sandi?</strong>.</li><li>Masukkan email yang terdaftar.</li><li>Klik tombol <strong>Kirim Tautan Atur Ulang</strong>.</li></ol><h3 id="mengatur-ulang-kata-sandi" tabindex="-1">Mengatur Ulang Kata Sandi <a class="header-anchor" href="#mengatur-ulang-kata-sandi" aria-label="Permalink to &quot;Mengatur Ulang Kata Sandi&quot;">​</a></h3><ol><li>Buka email yang dikirimkan aplikasi.</li><li>Klik tautan atur ulang kata sandi di dalam pesan tersebut.</li><li>Masukkan <strong>kata sandi baru</strong> dua kali.</li><li>Klik tombol <strong>Simpan</strong>.</li><li>Masuk kembali menggunakan kata sandi baru.</li></ol><h2 id="keluar-dari-akun" tabindex="-1">Keluar dari Akun <a class="header-anchor" href="#keluar-dari-akun" aria-label="Permalink to &quot;Keluar dari Akun&quot;">​</a></h2><ol><li>Klik menu <strong>Profil Saya</strong> atau ikon pengguna pada navigasi.</li><li>Klik <strong>Keluar</strong>.</li><li>Anda akan kembali ke halaman beranda dalam keadaan tidak masuk.</li></ol><h2 id="halaman-yang-membutuhkan-akun" tabindex="-1">Halaman yang Membutuhkan Akun <a class="header-anchor" href="#halaman-yang-membutuhkan-akun" aria-label="Permalink to &quot;Halaman yang Membutuhkan Akun&quot;">​</a></h2><p>Sebagian fitur hanya dapat digunakan setelah masuk. Berikut daftarnya:</p><ul><li>Mengedit profil (<code>/profil/edit</code>)</li><li>Membuat lowongan (<code>/lowongan/baru</code>)</li><li>Mendaftar sebagai mentor (<code>/mentoring/daftar-mentor</code>)</li><li>Mengajukan referral (<code>/referral/baru</code>)</li><li>Membuat grup (<code>/grup/baru</code>)</li><li>Membuat polling (<code>/polling/baru</code>)</li><li>Membuat pengumuman (<code>/pengumuman/baru</code>)</li></ul><p>Jika Anda belum masuk dan membuka salah satu halaman tersebut, aplikasi akan mengarahkan Anda ke halaman <strong>Masuk</strong> terlebih dahulu, lalu kembali ke halaman tujuan setelah masuk.</p><h2 id="peran-dan-hak-akses" tabindex="-1">Peran dan Hak Akses <a class="header-anchor" href="#peran-dan-hak-akses" aria-label="Permalink to &quot;Peran dan Hak Akses&quot;">​</a></h2><h3 id="alumni-terdaftar" tabindex="-1">Alumni Terdaftar <a class="header-anchor" href="#alumni-terdaftar" aria-label="Permalink to &quot;Alumni Terdaftar&quot;">​</a></h3><p>Pengguna yang sudah memverifikasi email dapat:</p><ul><li>Mengisi dan mengedit profil pribadi.</li><li>Bergabung dengan grup dan berpartisipasi dalam forum diskusi.</li><li>Memberi dukungan (endorsement) keahlian.</li><li>Mengajukan permintaan mentoring dan referral.</li><li>Membuat serta mengikuti polling.</li><li>Mengunggah foto ke galeri kegiatan.</li><li>Melaporkan konten yang tidak pantas.</li></ul><h3 id="alumni-terverifikasi" tabindex="-1">Alumni Terverifikasi <a class="header-anchor" href="#alumni-terverifikasi" aria-label="Permalink to &quot;Alumni Terverifikasi&quot;">​</a></h3><p>Alumni yang profilnya diverifikasi admin mendapatkan hak tambahan:</p><ul><li>Membuat <strong>lowongan kerja</strong>.</li><li>Membuat <strong>pengumuman</strong>.</li></ul><h3 id="admin-dan-super-admin" tabindex="-1">Admin dan Super Admin <a class="header-anchor" href="#admin-dan-super-admin" aria-label="Permalink to &quot;Admin dan Super Admin&quot;">​</a></h3><ul><li><strong>Admin</strong> mengelola modul sesuai kemampuan (capability) yang diberikan.</li><li><strong>Super Admin</strong> memiliki seluruh kemampuan, termasuk mengelola pengguna.</li></ul><p>Detail lengkap terdapat di bagian <a href="/webapps/latest/admin/">Panduan Admin</a>.</p><p>Lanjutkan ke <a href="/webapps/latest/profil">Profil &amp; Data Diri</a> untuk melengkapi profil Anda.</p>',36)])])}const h=n(r,[["render",t]]);export{g as __pageData,h as default};
